import{_ as d,o as a,c as e,b6 as r}from"./chunks/framework.COUcLbTA.js";const p=JSON.parse('{"title":"学习规划设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-18-learning-plan-design.md","filePath":"superpowers/specs/2026-05-18-learning-plan-design.md"}'),n={name:"superpowers/specs/2026-05-18-learning-plan-design.md"};function s(h,t,o,l,i,b){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="学习规划设计文档" tabindex="-1">学习规划设计文档 <a class="header-anchor" href="#学习规划设计文档" aria-label="Permalink to “学习规划设计文档”">​</a></h1><p><strong>日期</strong>：2026-05-18<br><strong>学习者</strong>：Penpey<br><strong>方案</strong>：A（按阶段顺序推进）</p><h2 id="学习者背景" tabindex="-1">学习者背景 <a class="header-anchor" href="#学习者背景" aria-label="Permalink to “学习者背景”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>情况</th></tr></thead><tbody><tr><td>编程基础</td><td>入门级（写过简单脚本，没有完整项目经验）</td></tr><tr><td>学习目标</td><td>掌握 AI 编程方法论</td></tr><tr><td>每周时间</td><td>8-15 小时（中等投入）</td></tr><tr><td>学习偏好</td><td>理论实践并行</td></tr></tbody></table><h2 id="整体节奏" tabindex="-1">整体节奏 <a class="header-anchor" href="#整体节奏" aria-label="Permalink to “整体节奏”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>预计时长</th></tr></thead><tbody><tr><td>Stage 1</td><td>AI IDE 入门 + 产品思维 + 原型开发</td><td>4-5 周</td></tr><tr><td>Stage 2</td><td>全栈开发 + 数据库 + 部署 + 大作业</td><td>8-10 周</td></tr><tr><td>Stage 3</td><td>Claude Code 进阶 + 多平台 + RAG/Agent</td><td>6-8 周</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>约 4-5 个月</strong></td></tr></tbody></table><h2 id="stage-1-详细安排-第-1-5-周" tabindex="-1">Stage 1 详细安排（第 1-5 周） <a class="header-anchor" href="#stage-1-详细安排-第-1-5-周" aria-label="Permalink to “Stage 1 详细安排（第 1-5 周）”">​</a></h2><p>每章节三步走：读文档 → 跟做示例 → 用自己的想法复现。</p><table tabindex="0"><thead><tr><th>周次</th><th>章节</th><th>重点</th></tr></thead><tbody><tr><td>第 1 周</td><td>AI IDE 入门 + 用游戏体验 AI 能力</td><td>装好工具，跑通第一个 AI 生成的程序</td></tr><tr><td>第 2 周</td><td>找到好想法 + 产品思维附录</td><td>学会用双钻模型和 Jobs-to-be-Done 拆解需求</td></tr><tr><td>第 3 周</td><td>构建原型 + 接入 AI 能力</td><td>做出第一个可演示的 Demo</td></tr><tr><td>第 4-5 周</td><td>完整项目实战</td><td>从想法到可跑的产品，走完完整流程</td></tr></tbody></table><h2 id="stage-2-详细安排-第-6-15-周" tabindex="-1">Stage 2 详细安排（第 6-15 周） <a class="header-anchor" href="#stage-2-详细安排-第-6-15-周" aria-label="Permalink to “Stage 2 详细安排（第 6-15 周）”">​</a></h2><table tabindex="0"><thead><tr><th>周次</th><th>模块</th><th>章节</th></tr></thead><tbody><tr><td>第 6-7 周</td><td>前端</td><td>UI 设计 → 组件库 → 设计稿转代码</td></tr><tr><td>第 8-9 周</td><td>后端</td><td>Git → 数据库/Supabase → API 设计</td></tr><tr><td>第 10 周</td><td>部署 + CLI</td><td>Zeabur 部署 + 现代 CLI 工具</td></tr><tr><td>第 11-13 周</td><td>大作业 1</td><td>文案生成 SaaS（登录/生成/支付/管理后台）</td></tr><tr><td>第 14-15 周</td><td>大作业 2（选做）</td><td>在线考试系统</td></tr></tbody></table><h2 id="stage-3-详细安排-第-16-22-周" tabindex="-1">Stage 3 详细安排（第 16-22 周） <a class="header-anchor" href="#stage-3-详细安排-第-16-22-周" aria-label="Permalink to “Stage 3 详细安排（第 16-22 周）”">​</a></h2><table tabindex="0"><thead><tr><th>周次</th><th>模块</th><th>章节</th></tr></thead><tbody><tr><td>第 16-17 周</td><td>Claude Code 核心</td><td>快速上手 + MCP + Skills + 工作流</td></tr><tr><td>第 18-19 周</td><td>高级工程</td><td>Agent Teams + Superpowers + 长任务</td></tr><tr><td>第 20-21 周</td><td>多平台（选一个）</td><td>微信小程序 / PWA / VSCode 插件</td></tr><tr><td>第 22 周</td><td>AI 进阶</td><td>RAG 入门 + LangGraph</td></tr></tbody></table><h2 id="学习原则" tabindex="-1">学习原则 <a class="header-anchor" href="#学习原则" aria-label="Permalink to “学习原则”">​</a></h2><ol><li><strong>每章节三步走</strong>：读文档 → 跟做示例 → 用自己的想法复现</li><li><strong>遇到不懂的概念</strong>：先去 Appendix 查对应章节，不要卡住超过 30 分钟</li><li><strong>每个阶段结束</strong>：做一个能演示的小项目，不要只看不做</li><li><strong>笔记记在 study-notes 分支</strong>：专门用来记录学习笔记和心得</li></ol>',15)])])}const c=d(n,[["render",s]]);export{p as __pageData,c as default};
